func parser16ErrorMessage(state, lookAhead int) string {
	const TOKSTART = 4

	if !parser16ErrorVerbose {
		return "syntax error"
	}

	for _, e := range parser16ErrorMessages {
		if e.state == state && e.token == lookAhead {
			return "syntax error: " + e.msg
		}
	}

	res := "syntax error: unexpected " + parser16Tokname(lookAhead)

	// To match Bison, suggest at most four expected tokens.
	expected := make([]int, 0, 4)

	// Look for shiftable tokens.
	base := int(parser16Pact[state])
	for tok := TOKSTART; tok-1 < len(parser16Toknames); tok++ {
		if n := base + tok; n >= 0 && n < parser16Last && int(parser16Chk[int(parser16Act[n])]) == tok {
			if len(expected) == cap(expected) {
				return res
			}
			expected = append(expected, tok)
		}
	}

	if parser16Def[state] == -2 {
		i := 0
		for parser16Exca[i] != -1 || int(parser16Exca[i+1]) != state {
			i += 2
		}

		// Look for tokens that we accept or reduce.
		for i += 2; parser16Exca[i] >= 0; i += 2 {
			tok := int(parser16Exca[i])
			if tok < TOKSTART || parser16Exca[i+1] == 0 {
				continue
			}
			if len(expected) == cap(expected) {
				return res
			}
			expected = append(expected, tok)
		}

		// If the default action is to accept or reduce, give up.
		if parser16Exca[i+1] != 0 {
			return res
		}
	}

	for i, tok := range expected {
		if i == 0 {
			res += ", expecting "
		} else {
			res += " or "
		}
		res += parser16Tokname(tok)
	}
	return res
}

